 // spaces, no '+' sign on the mantissa, no inf/nan/hex. Every value must be
 // bit-identical to std::strtod (correctly rounded, round-half-to-even).
 extern "C" size_t parse_doubles(const char* buf, size_t len, double* out) {
+    constexpr size_t FAST_INT_MAX_DIGITS = 19;
     const char* p = buf;
     const char* end = buf + len;
     size_t count = 0;
     while (p < end) {
-        char* next;
-        out[count++] = std::strtod(p, &next);
-        p = next;
-        while (p < end && *p == '\n') ++p;
+        const char* start = p;
+        bool neg = false;
+        if (*p == '-') { neg = true; ++p; }
+        const char* dig = p;
+        while (p < end && *p >= '0' && *p <= '9') ++p;
+        size_t ndig = (size_t)(p - dig);
+        bool fast = ndig >= 1 && ndig <= FAST_INT_MAX_DIGITS && p < end && *p == '\n';
+        if (fast) {
+            uint64_t m = 0;
+            const char* q = dig;
+            while (q < p) { m = m * 10u + (uint64_t)(*q - '0'); ++q; }
+            out[count++] = neg ? -((double)m) : (double)m;
+            ++p; // skip newline
+        } else {
+            char* next;
+            out[count++] = std::strtod(start, &next);
+            p = next;
+            while (p < end && *p == '\n') ++p;
+        }
     }
     return count;
 }
